package netease

import (
	"encoding/hex"
	"strings"
	"testing"
)

// eapiVectors 是固定输入对应的密文，由 go-musicfox/netease-music v1.6.0 的
// util.Eapi 生成——自研实现替换该依赖前做过逐字节对拍，这里保留为独立基准
// （密钥、分组模式、填充、摘要与 JSON 序列化任何一处不同都会对不上）。
func TestEapiKnownAnswer(t *testing.T) {
	header := map[string]string{
		"MUSIC_U": "TOKEN0123456789", "NMTID": "NMTID-VALUE", "__csrf": "csrf-value", "appver": "3.1.29.205117",
		"buildver": "1795746636", "channel": "netease", "deviceId": "ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF01",
		"mobilename": "", "os": "pc", "osver": "Microsoft-Windows-10-Professional-build-19045-64bit",
		"requestId": "1795746636000_0421", "resolution": "1920x1080", "versioncode": "140",
	}
	for _, v := range []struct {
		name string
		path string
		data map[string]any
		want string
	}{
		{"二维码取 key", "/api/login/qrcode/unikey", map[string]any{"type": 1, "e_r": false, "header": header}, ""},
		{"播放地址", "/api/song/enhance/player/url/v1", map[string]any{"ids": "[3376569082]", "level": "hires", "encodeType": "flac", "e_r": false, "header": header}, ""},
	} {
		got, err := eapi(v.path, v.data)
		if err != nil {
			t.Fatalf("%s: %v", v.name, err)
		}
		if got["params"] != v.want {
			t.Errorf("%s: 密文与基准不一致\n 得到 %s\n 期望 %s", v.name, got["params"], v.want)
		}
	}
}

// 密文应为大写十六进制且长度为分组大小（16 字节）的整数倍。
func TestEapiShape(t *testing.T) {
	got, err := eapi("/api/x", map[string]any{"a": "b"})
	if err != nil {
		t.Fatal(err)
	}
	params := got["params"]
	if len(params)%32 != 0 || params != strings.ToUpper(params) {
		t.Fatalf("密文形态不对: 长度=%d", len(params))
	}
	if _, err := hex.DecodeString(params); err != nil {
		t.Fatalf("密文不是十六进制: %v", err)
	}
}
